import re

def parse_duration(text: str) -> int:
    """Return the duration described by `text` in whole seconds. See README.md."""

    if not text:
        raise ValueError("Empty input")

    text = text.strip()

    # Try parsing as a bare integer first
    try:
        value = int(text)
        if value < 0:
            raise ValueError("Negative duration")
        return value
    except ValueError:
        pass

    # Try parsing as ISO 8601 duration (e.g., PT1H30M, P1DT2H)
    if text.startswith('P'):
        return _parse_iso8601(text)

    # Try parsing as clock notation (HH:MM:SS or MM:SS)
    if ':' in text:
        return _parse_clock_notation(text)

    # Try parsing as number+unit components
    return _parse_components(text)


def _parse_iso8601(text: str) -> int:
    """Parse ISO 8601 duration format."""
    # Pattern: P[n]Y[n]M[n]DT[n]H[n]M[n]S
    # We support: P[weeks]W[days]D T[hours]H[minutes]M[seconds]S

    if not text.startswith('P'):
        raise ValueError("Invalid ISO 8601 duration")

    text = text[1:]  # Remove 'P'

    total_seconds = 0.0

    # Split by 'T' to separate date and time parts
    if 'T' in text:
        date_part, time_part = text.split('T', 1)
    else:
        date_part = text
        time_part = ''

    # Parse date part
    # Pattern: [n]W[n]D
    date_pattern = r'(\d+(?:\.\d+)?)\s*([WD])'
    for match in re.finditer(date_pattern, date_part):
        value = float(match.group(1))
        unit = match.group(2)
        if unit == 'W':
            total_seconds += value * 7 * 24 * 3600
        elif unit == 'D':
            total_seconds += value * 24 * 3600

    # Parse time part
    # Pattern: [n]H[n]M[n]S
    time_pattern = r'(\d+(?:\.\d+)?)\s*([HMS])'
    for match in re.finditer(time_pattern, time_part):
        value = float(match.group(1))
        unit = match.group(2)
        if unit == 'H':
            total_seconds += value * 3600
        elif unit == 'M':
            total_seconds += value * 60
        elif unit == 'S':
            total_seconds += value

    if total_seconds < 0:
        raise ValueError("Negative duration")

    return round(total_seconds)


def _parse_clock_notation(text: str) -> int:
    """Parse clock notation HH:MM:SS or MM:SS."""
    parts = text.split(':')

    if len(parts) == 2:
        # MM:SS format
        try:
            minutes = int(parts[0])
            seconds = int(parts[1])
            total = minutes * 60 + seconds
            if total < 0:
                raise ValueError("Negative duration")
            return total
        except ValueError:
            raise ValueError("Invalid clock notation")
    elif len(parts) == 3:
        # HH:MM:SS format
        try:
            hours = int(parts[0])
            minutes = int(parts[1])
            seconds = int(parts[2])
            total = hours * 3600 + minutes * 60 + seconds
            if total < 0:
                raise ValueError("Negative duration")
            return total
        except ValueError:
            raise ValueError("Invalid clock notation")
    else:
        raise ValueError("Invalid clock notation")


def _parse_components(text: str) -> int:
    """Parse number+unit components like 1h30m or 1 hour 30 minutes."""

    # Define unit patterns and their conversions to seconds
    unit_patterns = {
        r'weeks?|w': 7 * 24 * 3600,
        r'days?|d': 24 * 3600,
        r'hours?|h': 3600,
        r'minutes?|mins?|m': 60,
        r'seconds?|secs?|s': 1,
    }

    total_seconds = 0.0

    # Pattern to match number (possibly fractional) followed by optional space and unit
    pattern = r'(\d+(?:\.\d+)?)\s*([a-zA-Z]+)'

    matches = list(re.finditer(pattern, text))

    if not matches:
        raise ValueError("No valid duration components found")

    # Check if the entire text was consumed by valid matches
    matched_text = ''.join(m.group(0) for m in matches)
    # Remove spaces for comparison since we allow optional spaces
    text_no_spaces = re.sub(r'\s+', '', text)
    matched_no_spaces = re.sub(r'\s+', '', matched_text)

    if matched_no_spaces != text_no_spaces:
        raise ValueError("Invalid duration format")

    for match in matches:
        value = float(match.group(1))
        unit_str = match.group(2).lower()

        # Find matching unit
        found = False
        for pattern, multiplier in unit_patterns.items():
            if re.fullmatch(pattern, unit_str):
                total_seconds += value * multiplier
                found = True
                break

        if not found:
            raise ValueError(f"Unknown unit: {unit_str}")

    if total_seconds < 0:
